 * The seven-step, server-authoritative price quote (Part 4.1 / V6 8.2):
 *
 *   1. BASE PRICE    → PricingEngine (six-rank hierarchy)
 *   2. QTY BREAK     → PricingEngine
 *   3. DISCOUNTS     → product policy × tier ceiling × role authority, most restrictive wins
 *   4. BONUS         → BonusResolver (free goods as quantity, never as discount)
 *   5. MARGIN GUARD  → floor_price = cost ÷ (1 − min_margin_pct) — hard stop
 *   6. TAX           → TaxResolver, line level, on net after discount
 *   7. ROUNDING      → product round_to, applied last, floor re-checked
 *
 * Every quote is written to price_quote_logs (immutable) and carries an
 * explain[] trail. The client never calculates the final price: checkout
 * re-validates the quote_id and refuses to post if anything moved.
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:20:"App\Services\Pricing";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:9:{s:8:"customer";s:19:"App\Models\Customer";s:13:"pricequotelog";s:24:"App\Models\PriceQuoteLog";s:7:"product";s:18:"App\Models\Product";s:21:"productdiscountpolicy";s:32:"App\Models\ProductDiscountPolicy";s:10:"productuom";s:21:"App\Models\ProductUom";s:7:"setting";s:18:"App\Models\Setting";s:4:"user";s:15:"App\Models\User";s:6:"carbon";s:25:"Illuminate\Support\Carbon";s:3:"str";s:22:"Illuminate\Support\Str";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:4:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:11:"__construct";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";N;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";N;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:5:{i:0;O:53:"PHPStan\Dependency\ExportedNode