 * Part 21.16 — the statutory leave types every organisation starts with
 * (Employment Act 2007, Cap. 226).
 *
 * [ASSUMPTION] Annual 21 working days (s.28), maternity 90 days (s.29),
 * paternity 14 days (s.29(8)), compassionate 5 days (common practice; not
 * statutory). Sick leave under s.30 is 7 days full pay then 7 days half pay
 * after two months' service; it is modelled here as 14 paid days and the
 * half-pay split is left to the payroll officer — confirm with HR before
 * the first live leave year. Unpaid leave has no entitlement and never
 * blocks on balance.
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:16:"Database\Seeders";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:3:{s:9:"leavetype";s:20:"App\Models\LeaveType";s:12:"organisation";s:23:"App\Models\Organisation";s:6:"seeder";s:26:"Illuminate\Database\Seeder";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";s:26:"Illuminate\Database\Seeder";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:3:{i:0;O:58:"PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode":5:{s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀constants";a:1:{i:0;O:57:"PHPStan\Dependency\ExportedNode\ExportedClassConstantNode":3:{s:63:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀name";s:5:"TYPES";s:64:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀value";s:439:"[
